# Purpose: tests of what the app shows for a model whose cost isn't in dollars (a GitHub
#          Copilot one; ds.ai.model.spend_tracked): usage is tokens and requests, with no
#          dollar figure kept or shown, and the Spend tab and meters follow the same switch.
# Usage: uv run pytest tests/services/ui/test_copilot_costs.py
# ---------------------------------------------------------------------------
from __future__ import annotations

import pytest
from ds.ai.model import spend_tracked
from ds.util.const import DEFAULT_AI_MODEL
from pydantic_ai.messages import ModelResponse, TextPart
from pydantic_ai.usage import RequestUsage
from ui import session, spend
from ui.session import TurnUsage

ANSWER = [ModelResponse(parts=[TextPart("hi")], usage=RequestUsage(input_tokens=1200, output_tokens=30))]


def test_without_dollars_usage_is_tokens_and_requests_only(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(session, "DOLLARS", False)
    usage = TurnUsage.of(ANSWER)
    assert usage.summary() == "1.2k in · 30 out · 1 request"
    assert usage.cost is None  # nothing is added to the session's cost
    assert "$" not in usage.lines[0]
    call: dict[str, object] = {}
    usage.log_to(call)
    assert call["cost"] is None  # the debug log's row leaves the cost out


def test_with_dollars_the_cost_leads_the_line() -> None:
    assert TurnUsage.of(ANSWER).summary().startswith("$")  # conftest: DOLLARS on


def test_the_switches_follow_the_model_setting() -> None:
    # read once at import from DEFAULT_AI_MODEL: the Spend tab, its meters, the usage lines
    assert spend.AVAILABLE is spend_tracked(DEFAULT_AI_MODEL)


def test_a_copilot_turn_leads_its_line_with_the_credits_its_answers_cost(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(session, "DOLLARS", False)
    usage = TurnUsage.of(ANSWER)
    usage.log_to({"credits": 0.1234})  # left on the call's record by ds.ai.model
    assert usage.summary() == "0.12 credits · 1.2k in · 30 out · 1 request"


@pytest.mark.parametrize(
    ("spent", "text"),
    [
        (0, "0 credits"),
        (0.00078, "0.00078 credits"),
        (0.1234, "0.12 credits"),
        (4.5, "4.5 credits"),
        (12, "12 credits"),
    ],
)
def test_credits_keep_two_digits_under_one(spent: float, text: str) -> None:
    assert session.credits_text(spent) == text
